package vn.covie.inventory.application;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.catalog.model.*; import vn.covie.catalog.persistence.*; import vn.covie.inventory.api.dto.InventoryItemResponse; import vn.covie.inventory.persistence.InventoryBalanceRepository; import vn.covie.merchants.persistence.MerchantLocationRepository; import vn.covie.merchants.security.*;
@Service public class InventoryQueryService{private final MerchantAccessPolicy access;private final MerchantLocationRepository locations;private final LocationVariantRepository offers;private final VariantRepository variants;private final CatalogItemRepository items;private final InventoryBalanceRepository balances;public InventoryQueryService(MerchantAccessPolicy access,MerchantLocationRepository locations,LocationVariantRepository offers,VariantRepository variants,CatalogItemRepository items,InventoryBalanceRepository balances){this.access=access;this.locations=locations;this.offers=offers;this.variants=variants;this.items=items;this.balances=balances;}@Transactional(readOnly=true)public List<InventoryItemResponse> list(UUID merchantId){access.require(merchantId,MerchantCapability.MANAGE_LOCATION_OFFER);return locations.findAllByMerchantProfileIdAndDeletedAtIsNullOrderByNameAscIdAsc(merchantId).stream().flatMap(l->offers.findAllByMerchantLocationIdAndDeletedAtIsNull(l.getId()).stream().map(o->{var v=variants.findById(o.getVariantId()).orElseThrow();var i=items.findById(v.getCatalogItemId()).orElseThrow();if(i.getItemType()!=CatalogItemType.PRODUCT)return null;var b=o.getInventoryMode()==InventoryMode.TRACKED?balances.findById(o.getId()).orElse(null):null;return new InventoryItemResponse(o.getId(),i.getId(),i.getName(),v.getId(),v.getVariantName(),l.getId(),l.getName(),o.getInventoryMode(),b==null?null:b.getStockOnHand(),b==null?null:b.getReservedQuantity(),b==null?null:b.availableQuantity(),b==null?0:b.getVersion());}).filter(Objects::nonNull)).toList();}}
